contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: try to call getTokens with an ETH amount and assert relation
    function run(uint256 sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendAmount)); require(sendAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= sendAmount);

        // read pre-state
        uint256 totalDistributedBefore = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 totalRemainingBefore = c.totalRemaining(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool blacklistedBefore = c.blacklist(address(this)); if (__ESBMC_reverted()) return;

        // perform call and catch revert
        bool reverted;
        c.getTokens{value: sendAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read post-state
        uint256 totalDistributedAfter = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 totalRemainingAfter = c.totalRemaining(); if (__ESBMC_reverted()) return;
        uint256 balanceAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool blacklistedAfter = c.blacklist(address(this)); if (__ESBMC_reverted()) return;

        // Compute observed increments (use non-underflowing comparisons)
        uint256 distInc = totalDistributedAfter >= totalDistributedBefore ? totalDistributedAfter - totalDistributedBefore : 0;
        uint256 balInc = balanceAfter >= balanceBefore ? balanceAfter - balanceBefore : 0;
        uint256 remDec = totalRemainingBefore >= totalRemainingAfter ? totalRemainingBefore - totalRemainingAfter : 0;

        // General rule:
        // - If reverted then no observable token/state change (distributions unchanged, balance unchanged, blacklist unchanged)
        // - If not reverted then: balInc == distInc, remDec == distInc, balInc <= totalRemainingBefore, and caller becomes blacklisted (blacklist flips to true)
        assert(
            (reverted && distInc == 0 && balInc == 0 && remDec == 0 && blacklistedAfter == blacklistedBefore)
            ||
            (!reverted && distInc == balInc && remDec == distInc && balInc <= totalRemainingBefore && blacklistedAfter == true)
        );
    }

    receive() external payable {}
}

