pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 sendAmount) internal {
        sendAmount = bound(sendAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        uint256 totalDistributedBefore;
        try c.totalDistributed() returns (uint256 __r) { totalDistributedBefore = __r; } catch { return; }
        uint256 totalRemainingBefore;
        try c.totalRemaining() returns (uint256 __r) { totalRemainingBefore = __r; } catch { return; }
        uint256 balanceBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balanceBefore = __r; } catch { return; }
        bool blacklistedBefore;
        try c.blacklist(address(this)) returns (bool __r) { blacklistedBefore = __r; } catch { return; }
        bool reverted;
        try c.getTokens{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 totalDistributedAfter;
        try c.totalDistributed() returns (uint256 __r) { totalDistributedAfter = __r; } catch { return; }
        uint256 totalRemainingAfter;
        try c.totalRemaining() returns (uint256 __r) { totalRemainingAfter = __r; } catch { return; }
        uint256 balanceAfter;
        try c.balanceOf(address(this)) returns (uint256 __r) { balanceAfter = __r; } catch { return; }
        bool blacklistedAfter;
        try c.blacklist(address(this)) returns (bool __r) { blacklistedAfter = __r; } catch { return; }
        uint256 distInc = totalDistributedAfter >= totalDistributedBefore ? totalDistributedAfter - totalDistributedBefore : 0;
        uint256 balInc = balanceAfter >= balanceBefore ? balanceAfter - balanceBefore : 0;
        uint256 remDec = totalRemainingBefore >= totalRemainingAfter ? totalRemainingBefore - totalRemainingAfter : 0;
        assertTrue((reverted && distInc == 0 && balInc == 0 && remDec == 0 && blacklistedAfter == blacklistedBefore)
            ||
            (!reverted && distInc == balInc && remDec == distInc && balInc <= totalRemainingBefore && blacklistedAfter == true));
    }

    function testFuzz_run(uint256 sendAmount) public {
        _run(sendAmount);
    }

    receive() external payable {}
}
